const items = $input.all();
const baseUrl = String($env.PODCAST_PUBLIC_URL || '').replace(/\/+$/, '');
const results = [];
const seenGuids = new Set();

items.forEach((item, index) => {
  const rssItem = $('Read RSS Feed').all()[index]?.json || {};

  const rawDescription = (
    rssItem.description ||
    rssItem.content ||
    rssItem.contentSnippet ||
    rssItem.summary ||
    rssItem['content:encoded'] ||
    ""
  );

  // 1. Extract TL;DR from HTML or plaintext description
  let tldr = "";
  const match = rawDescription.match(/TL;?DR:?\s*<\/strong>\s*([\s\S]*?)(?:<\/p>|<p>|<strong>|\n|$)/i) 
             || rawDescription.match(/TL;?DR:?\s*([\s\S]*?)(?:Paper Link:|https?:\/\/|\n\n|$)/i);

  if (match) {
    tldr = match[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  }

  // 2. Validate HTML transcript (reject 404 pages)
  let rawContent = "";
  if (item.json && item.json.data && !item.json.error && typeof item.json.data === 'string') {
    const is404 = /404\s*not\s*found/i.test(item.json.data);
    if (!is404 && item.json.data.trim().length > 100) {
      rawContent = item.json.data;
    }
  }

  // Fallback to RSS description if no external HTML transcript exists
  if (!rawContent) {
    rawContent = rawDescription;
  }

  const cleanText = rawContent
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  if (cleanText.length > 20) {
    let rawGuid = rssItem.guid;
    if (typeof rawGuid === 'object' && rawGuid !== null) {
      rawGuid = rawGuid._ || rawGuid.text || "";
    }
    if (!rawGuid && rssItem.enclosure && rssItem.enclosure.url) {
      const parts = rssItem.enclosure.url.split('/');
      rawGuid = parts[parts.length - 1].replace('.mp3', '');
    }

    if (!rawGuid || seenGuids.has(rawGuid)) return;
    seenGuids.add(rawGuid);

    const title = rssItem.title || "Untitled Episode";
    const arxivMatch = title.match(/arXiv:\s*(\d{4}\.\d{4,5})/i) || cleanText.match(/arXiv:\s*(\d{4}\.\d{4,5})/i);
    const arxivId = arxivMatch ? arxivMatch[1] : "";
    const paperLink = rssItem.link || (arxivId ? `https://arxiv.org/abs/${arxivId}` : "");

    if (!tldr) {
      tldr = cleanText.slice(0, 180) + '...';
    }

    results.push({
      json: {
        id: rawGuid,
        text: cleanText,
        pageContent: cleanText,
        title: title,
        arxiv_id: arxivId,
        link: paperLink,
        audio_url: `${baseUrl}/${rawGuid}.mp3`,
        transcript_url: `${baseUrl}/${rawGuid}.html`,
        tldr: tldr,
        created_at: rssItem.pubDate || new Date().toISOString()
      }
    });
  }
});

return results;
